CREATE TYPE battery_efficiency_enum AS ENUM ('Poor Efficiency', 'Average Efficiency', 'Good Efficiency', 'Excellent Efficiency');

CREATE OR REPLACE FUNCTION classify_battery_efficiency()
RETURNS TABLE (device_id VARCHAR, efficiency_value NUMERIC, classification battery_efficiency_enum)
AS $$
BEGIN
    RETURN QUERY SELECT d.devregistry, ROUND(CAST((t.battlifeh * t.battcapmah) / (d.pwractmw * 10) AS numeric), 2), CASE WHEN (t.battlifeh * t.battcapmah) / (d.pwractmw * 10) > 7.5 THEN 'Excellent Efficiency'::battery_efficiency_enum WHEN (t.battlifeh * t.battcapmah) / (d.pwractmw * 10) >= 5.0 THEN 'Good Efficiency'::battery_efficiency_enum WHEN (t.battlifeh * t.battcapmah) / (d.pwractmw * 10) >= 2.5 THEN 'Average Efficiency'::battery_efficiency_enum ELSE 'Poor Efficiency'::battery_efficiency_enum END FROM deviceidentity d JOIN testsessions t ON d.devsessionref = t.sessionregistry WHERE d.conntype IN ('Wireless 2.4GHz', 'Bluetooth', 'Hybrid');
END;
$$ LANGUAGE plpgsql;

